mapper.update:
UPDATE COMTNBBS SET
	NTT_SJ = #{nttSj},
	NTT_CN = #{nttCn},
	NOTICE_AT = #{noticeAt},
	LAST_UPDUSR_ID = #{audit.userId},
	LAST_UPDT_PNTTM = #{audit.now}
WHERE BBS_ID = #{bbsId}
AND NTT_ID = #{nttId}
AND USE_AT = 'Y'

UPDATE COMTNBBS SET
	USE_AT = 'N',
	LAST_UPDUSR_ID = #{audit.userId},
	LAST_UPDT_PNTTM = #{audit.now}
WHERE BBS_ID = #{bbsId}
AND NTT_ID = #{nttId}
AND USE_AT = 'Y'

UPDATE COMTNBBS SET
	RDCNT = IFNULL(RDCNT, 0) + 1
WHERE BBS_ID = #{bbsId}
AND NTT_ID = #{nttId}
AND USE_AT = 'Y'
